const raw = ($input.first().json.output ?? '').trim();
const cleaned = raw.replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '').trim();
let data;
try {
  data = JSON.parse(cleaned);
} catch (err) {
  data = {
    resumen_general: raw,
    evaluacion_parametros: {},
    recomendaciones_generales: [],
    nivel_fatiga_final: '',
    aviso: 'Este analisis es orientativo y preventivo; no reemplaza la evaluacion de un profesional de la salud visual.'
  };
}
return [{ json: data }];
